  async function storage(){const d=await req('GET','/storage'+qs({courseId:activeId()}));state.storage=d.items||[];el('storage-summary').innerHTML=stat('Archivos registrados',number(d.total))+stat('Tamaño conocido',bytes(d.knownBytes),'Archivos originales registrados')+stat('Sin tamaño disponible',number(d.unknownSizeCount))+stat('Capacidad contratada',bytes(d.capacityBytes));el('storage-explanation').textContent='El tamaño mostrado corresponde a los archivos registrados con medición disponible. No representa el espacio total ni el tráfico facturado por tu proveedor.';renderStorage();}
  function renderStorage(){const query=el('storage-search').value.toLowerCase(),kind=el('storage-kind').value;const rows=state.storage.filter(i=>(!kind||i.kind===kind)&&(!activeId()||i.courseId===activeId())&&String(i.name||'').toLowerCase().includes(query));const area=el('workspace-storage');area.innerHTML=rows.length?table(['Archivo','Tipo','Acceso','Tamaño','Acciones'],rows.map((r,index)=>'<tr><td>'+h(r.name)+'</td><td>'+h(r.kind==='video'?'Video':'Recurso')+'</td><td>'+h(r.kind==='video'?'Licencia':r.protection==='protected'?'Protegido':'Libre')+'</td><td>'+bytes(r.byteSize)+'</td><td id="storage-action-'+index+'"></td></tr>').join('')):empty('No hay archivos para mostrar');rows.forEach((r,index)=>{el('storage-action-'+index).append(button('Administrar',async()=>{if(r.kind==='video'){const v=allVideos().find(v=>v.videoId===r.id);if(v)editVideo(v);else await navigate('videos');}else openResourceEditor(r.targetKind||'module',r.targetId||r.moduleId,r.name);}));});}

  /* ── Licencias y lotes: vista compacta de claves completas ─────────────── */
  const availabilityLabel = l => l.availability==='in_use'?'En uso'+(l.studentEmail||l.customerEmail?' · '+(l.studentName?l.studentName+' · ':'')+(l.studentEmail||l.customerEmail):''):l.availability==='reserved'?'Reservada para '+(l.customerEmail||l.reservedEmail):statusNames[l.availability]||l.availability;
  async function lots(){
    const version=state.version;const d=await req('GET','/lots'+qs({courseId:activeId()}));if(version!==state.version)return;state.lots=d.lots||[];
    const filter=el('license-lot-filter'),old=filter.value;filter.innerHTML='<option value="">Todos los lotes</option>'+state.lots.map(l=>'<option value="'+h(l.id)+'">'+h(l.name||l.courseName||l.id)+' · '+number(l.availableCount)+' disp. / '+number(l.total)+'</option>').join('');filter.value=state.lots.some(l=>l.id===old)?old:'';
    renderLotToolbar();
  }
  function renderLotToolbar(){const area=el('lot-toolbar');if(!area)return;const lot=state.lots.find(l=>l.id===el('license-lot-filter').value);area.replaceChildren();if(!lot){area.hidden=true;return;}area.hidden=false;
    const text=document.createElement('div');text.className='lot-summary';text.innerHTML='<strong>'+h(lot.name||'Lote sin nombre')+'</strong><span class="muted">'+h(lot.courseName)+' · creado '+h(date(lot.createdAt))+' · '+number(lot.availableCount)+' disponibles · '+number(lot.inUseCount)+' en uso'+(lot.reservedCount?' · '+number(lot.reservedCount)+' reservadas':'')+(lot.suspendedCount?' · '+number(lot.suspendedCount)+' suspendidas':'')+(lot.revokedCount?' · '+number(lot.revokedCount)+' revocadas':'')+'</span>';
    const actions=document.createElement('div');const recoverable=Number(lot.exportableCount)===Number(lot.total);
    fillActions(actions,[button('Copiar disponibles',async b=>{const d=await req('GET','/lots/'+encodeURIComponent(lot.id)+'/serials?scope=available');if(!d.serials.length)throw new Error('Este lote no tiene claves disponibles para copiar.');await copyText(d.serials.join('\n'),b,'Copiar disponibles');message('app-msg',number(d.serials.length)+' claves disponibles copiadas.','ok');},{disabled:!lot.availableCount}),button('Descargar CSV (disponibles)',()=>downloadLot(lot,'available'),{disabled:!lot.availableCount}),button('Descargar CSV (todas)',()=>downloadLot(lot,'all'),{disabled:!lot.total||!recoverable}),button('Editar lote',()=>editLot(lot)),button('Mover claves',()=>moveLot(lot),{disabled:!state.lots.some(l=>l.id!==lot.id&&l.courseId===lot.courseId)})]);
    area.append(text,actions);if(!recoverable){const warning=document.createElement('p');warning.className='muted';warning.textContent='Este lote contiene claves históricas no recuperables. Reemplázalas desde Administrar para volver a entregarlas.';area.append(warning);}}
  function editLot(lot){showDialog('Editar lote','<div class="form-grid">'+field('name','Nombre del lote',lot.name||'','text',{required:true,maxLength:120,wide:true})+field('notes','Notas internas',lot.notes||'','textarea',{wide:true})+'</div>',async d=>{await req('PATCH','/lots/'+encodeURIComponent(lot.id),d);await lots();});}
  function moveLot(lot){const choices=state.lots.filter(l=>l.id!==lot.id&&l.courseId===lot.courseId).map(l=>({value:l.id,label:l.name||l.id}));if(!choices.length)return;showDialog('Mover las claves del lote','<p class="notice">Las claves se trasladan al lote de destino dentro del mismo proyecto. Conservan su estado y su alumno.</p>'+field('targetLotId','Lote de destino',choices[0].value,'select',{choices}),async d=>{await req('POST','/lots/'+encodeURIComponent(lot.id)+'/move',{targetLotId:d.targetLotId});await lots();await licenses(1);},'Mover claves');}
  async function downloadLot(lot,scope='all'){const response=await fetch(base+'/lots/'+encodeURIComponent(lot.id)+'/export.csv?scope='+encodeURIComponent(scope),{headers:{Authorization:'Bearer '+TOKEN}});if(!response.ok){const d=await response.json().catch(()=>({}));throw new Error(d.error||'No se pudo descargar el lote.');}const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='edulock-licencias-'+(scope==='available'?'disponibles-':'')+String(lot.id).replace(/[^a-z0-9-]/gi,'')+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function licenseStatusParam(){if(state.licenseTab)return state.licenseTab;return el('license-status-filter').value||'';}
  function renderLicenseTabs(counts){const tabs=el('license-tabs');if(!tabs)return;const values={available:counts?.available,in_use:counts?.inUse,'':counts?.total};tabs.querySelectorAll('.tab').forEach(tab=>{const selected=tab.dataset.status===state.licenseTab;tab.classList.toggle('active',selected);tab.setAttribute('aria-selected',String(selected));const count=tab.querySelector('.count');if(count)count.textContent=number(values[tab.dataset.status]);});const secondary=el('license-status-filter');if(secondary)secondary.closest('label').hidden=state.licenseTab!=='';}
  function licenseRow(l){const row=document.createElement('div');row.className='license-row availability-'+h(l.availability);const key=document.createElement('div');key.className='license-key';
    if(l.serial){const code=document.createElement('code');code.textContent=l.serial;code.setAttribute('aria-label','Licencia '+l.serial);key.append(code);}else{const missing=document.createElement('span');missing.className='muted key-missing';missing.textContent='Clave histórica no recuperable · terminada en '+(l.serialSuffix||'????');key.append(missing);}
    const meta=document.createElement('div');meta.className='license-meta';meta.innerHTML=status(l.availability)+'<span>'+h(availabilityLabel(l))+'</span>'+(activeId()?'':'<span class="muted">'+h(l.courseName||'Sin curso')+'</span>')+(l.lotName?'<span class="muted">Lote: '+h(l.lotName)+'</span>':'');
    const actions=document.createElement('div');const items=[];if(l.serial&&l.availability!=='revoked')items.push(button('Copiar',b=>copyText(l.serial,b)));items.push(button('Administrar',()=>editLicense(l)));fillActions(actions,items);row.append(key,meta,actions);return row;}
  async function licenses(page=state.licensePage){const request=++_licenseRequest;const list=el('license-list');const msg=el('license-list-msg');if(msg)msg.textContent='';
    try {const d=await req('GET','/licenses'+qs({courseId:activeId(),lotId:el('license-lot-filter').value,q:el('license-search').value.trim(),status:licenseStatusParam(),page:Math.max(1,page||1),pageSize:30}));if(request!==_licenseRequest)return;state.licenses=d.licenses||[];state.licensePage=d.page||1;_licensePage=state.licensePage;state.licenseCounts=d.counts||null;renderLicenseTabs(d.counts);list.replaceChildren();
      if(!state.licenses.length)list.innerHTML=empty(state.licenseTab==='available'?'No hay claves disponibles':'No hay licencias en esta búsqueda',state.licenseTab==='available'?'Genera un lote o revisa En uso y Todas.':'Prueba otro proyecto, lote, pestaña o búsqueda.');
      for(const l of state.licenses)list.append(licenseRow(l));
      el('license-page').textContent='Página '+state.licensePage+' · '+number(d.total)+' licencias';el('license-prev').disabled=state.licensePage<=1;el('license-next').disabled=state.licensePage*(d.pageSize||30)>=(d.total||0);
    }catch(error){if(request===_licenseRequest)list.innerHTML='<p class="err">'+h(error.message)+'</p>';}}
  function licenseActions(l,after){const actions=[];if(l.status!=='revoked'){actions.push(button(l.status==='suspended'?'Reactivar acceso':'Suspender acceso',()=>confirmAction(l.status==='suspended'?'Reactivar licencia':'Suspender licencia',l.status==='suspended'?'Se restablecerá el acceso del alumno a este curso. Deberá volver a activar sus dispositivos.':'Se retirará temporalmente el acceso a este curso. Podrás reactivar esta licencia después.',async()=>{await req('POST','/licenses/'+encodeURIComponent(l.id)+'/status',{status:l.status==='suspended'?'active':'suspended'});await refreshLicenses();},l.status==='suspended'?'Reactivar':'Suspender',after)));actions.push(button('Reemplazar clave',()=>reissueLicense(l,after)));actions.push(button('Revocar',()=>confirmAction('Revocar licencia','Retira el acceso y las activaciones de forma definitiva. No devuelve cupo ni permite reactivar esta licencia.',async()=>{await req('POST','/licenses/'+encodeURIComponent(l.id)+'/status',{status:'revoked'});await refreshLicenses();},'Revocar licencia',after),{danger:true}));}
    if(l.availability==='in_use'&&l.serialAvailable){actions.push(button('Enviar acceso por correo',()=>emailLicense(l),{disabled:!state.mailConfigured||l.status!=='active'||!(l.customerEmail||l.studentEmail)}));actions.push(button('Enviar acceso manual',()=>openManualLicenseDialog(l),{disabled:l.status!=='active'}));}
    actions.push(button('Ver dispositivos',()=>licenseDevices(l,after)));return actions;}
  function editLicense(l){const free=l.availability==='available'||l.availability==='reserved';
    const body='<div class="detail-grid license-detail">'+info('Clave',l.serial?'<code class="key-inline">'+h(l.serial)+'</code>':'<span class="warn">Clave histórica no recuperable (terminada en '+h(l.serialSuffix||'????')+'). Usa Reemplazar clave.</span>')+info('Disponibilidad',status(l.availability)+' <span class="muted">'+h(availabilityLabel(l))+'</span>')+info('Curso',h(l.courseName||'Sin curso'))+info('Lote',h(l.lotName||'Sin lote'))+info('Creada',h(date(l.createdAt)))+info('Asignada',l.assignedAt?h(date(l.assignedAt)):'')+info('Dispositivos',number(l.activeActivations)+' activos de '+number(l.maxDevices)+' <span class="muted">(límite fijado por el administrador)</span>')+(l.suspendedAt?info('Suspendida desde',h(date(l.suspendedAt))):'')+(l.revokedAt?info('Revocada',h(date(l.revokedAt))):'')+'</div>'
      +(free&&l.status!=='revoked'?'<div class="form-grid section-spacer">'+field('customerEmail','Reservar para (correo, opcional)',l.customerEmail||l.reservedEmail||'','email',{wide:true,hint:'La clave sigue libre hasta que ese alumno la active. Deja vacío para no reservarla.'})+'</div>':'')
      +'<div id="license-edit-actions" class="actions section-spacer"></div>';
    showDialog('Administrar licencia',body,free&&l.status!=='revoked'?async d=>{await req('PATCH','/licenses/'+encodeURIComponent(l.id),{customerEmail:d.customerEmail||null});await refreshLicenses();}:null,'Guardar reserva');
    const actions=[];if(l.serial&&l.status!=='revoked')actions.unshift(button('Copiar clave',b=>copyText(l.serial,b)));if(l.studentId)actions.push(button('Abrir ficha del estudiante',()=>openStudent(l.studentId),{primary:true}));actions.push(...licenseActions(l,()=>{}));
    fillActions(el('license-edit-actions'),actions);if(!state.mailConfigured&&l.availability==='in_use'){const notice=document.createElement('p');notice.className='muted';notice.textContent='Correo no configurado. Puedes compartir la clave manualmente.';el('license-edit-actions').after(notice);}
  }
  function mailResultMessage(result) {
    if(result?.status==='accepted')return 'Correo aceptado por el proveedor. Esto no confirma la entrega en la bandeja del alumno.';
    if(result?.status==='queued')return 'Correo preparado para envío. Puedes consultar su estado en Integraciones.';
    if(result?.status==='sending')return 'El envío está en curso. Puedes consultar su estado en Integraciones.';
    const errors={failed:'El envío anterior falló. Revisa el historial de correos antes de volver a intentarlo.',cancelled:'El envío está cancelado. Revisa la licencia y el historial antes de volver a intentarlo.',manual_review:'El envío requiere revisión. Su entrega no está confirmada; consulta el historial de correos.'};
    throw new Error(errors[result?.status]||'No se pudo confirmar el estado del correo. Revisa el historial antes de repetir el envío.');
  }
  function isManualFallbackError(error) {
    return error?.code === 'MAIL_NOT_CONFIGURED' || error?.code === 'MAIL_RETRY_REQUIRED' || error?.code === 'LICENSE_SERIAL_UNAVAILABLE'
      || error?.code === 'CUSTOMER_EMAIL_REQUIRED' || error?.code === 'MAIL_ERROR' || error?.status === 503;
  }
  async function openManualLicenseDialog(license) {
    const data = await req('GET', '/licenses/' + encodeURIComponent(license.id) + '/key');
    showDialog('Clave para envío manual',
      '<p class="muted">Comparte esta clave por el canal que prefieras (correo personal, WhatsApp o chat seguro).</p>'
      + field('manualLicenseKey', 'Clave de acceso', data.key, 'textarea', { readonly: true, wide: true }) +
      '<div id="manual-license-actions" class="actions"></div>', null);
    el('manual-license-actions').append(button('Copiar clave', async () => {
      await navigator.clipboard.writeText(data.key);
      el('workspace-dialog-msg').textContent = 'Clave copiada.';
    }));
  }
  function emailLicense(license) {
    showDialog('Enviar acceso por correo','<p>Se solicitará el envío de la clave a <strong>'+h(license.customerEmail||license.studentEmail||'el alumno')+'</strong>.</p>',async()=>{
      try {
        const result=await req('POST','/licenses/'+encodeURIComponent(license.id)+'/email',{});
        const outcome=mailResultMessage(result);
        showDialog('Estado del correo','<p>'+h(outcome)+'</p>',null);
        return false;
      } catch (error) {
        if (isManualFallbackError(error)) {
          showDialog('El envío por correo no se pudo completar',
            '<p class="notice">No se pudo enviar por correo automáticamente, así que la entrega manual queda habilitada.</p><p>Clave del alumno:</p>', null);
          await openManualLicenseDialog(license);
          return false;
        }
        throw error;
      }
    },'Preparar envío');
  }
  async function refreshLicenses(){await Promise.allSettled([lots(),licenses(),refreshProfile()]);}
  function reissueLicense(l,after){showDialog('Reemplazar la clave de acceso','<p class="notice">La clave anterior dejará de funcionar y se invalidarán sus activaciones. El alumno necesitará la nueva clave y volver a activar sus dispositivos. Se conservan el alumno, el curso y el límite de dispositivos.</p>',async()=>{const d=await req('POST','/licenses/'+encodeURIComponent(l.id)+'/reissue',{confirm:true});await refreshLicenses();showDialog('Nueva clave de acceso',field('reissuedKey','Comparte esta clave con el alumno',d.key,'textarea',{readonly:true})+'<p class="muted">La clave queda guardada: también la verás completa en la lista de licencias.</p><div id="reissue-copy" class="actions"></div>',null);el('reissue-copy').append(button('Copiar clave',async()=>{await navigator.clipboard.writeText(d.key);el('workspace-dialog-msg').textContent='Clave copiada.';}));if(after)el('reissue-copy').append(button('Volver a la ficha',()=>after()));return false;},'Reemplazar e invalidar la anterior');}
