  async function loadSection(){const page=state.page;try{if(page==='proyectos'){await refreshProjects();await overview();}if(page==='videos'){await refreshProjects();}if(page==='licencias'){await lots();await licenses(1);}if(page==='estudiantes'){await refreshProjects();await students(1);}if(page==='almacenamiento')await storage();if(page==='integraciones')await integrations();if(page==='proteccion')await security();if(page==='cuenta')await Promise.all([account(),services()]);}catch(error){message('app-msg',error.message,'err');}}
  async function navigate(target,{push=false}={}){
    let [page,courseId]=String(target||'').split('/');page=pageAliases[page]||page;
    if(courseId&&courseId!==activeId()&&state.projects.some(p=>p.id===courseId)){el('up-course').value=courseId;await original.selectCourse();state.version++;}
    state.page=Object.hasOwn(pages,page)?page:'proyectos';
    document.querySelectorAll('[data-workspace-page]').forEach(section=>{section.hidden=section.dataset.workspacePage!==state.page;});
    document.querySelectorAll('[data-page]').forEach(b=>{const selected=b.dataset.page===state.page;b.classList.toggle('active',selected);if(selected)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
    el('workspace-title').textContent=pages[state.page];el('workspace-nav').classList.remove('open');el('menu-toggle').setAttribute('aria-expanded','false');
    const context=document.querySelector('.project-context');if(context)context.hidden=state.page==='proyectos';
    closeMenu();
    const hash='#'+state.page+(state.page==='videos'&&activeId()?'/'+activeId():'');
    if(location.hash!==hash){if(push)history.pushState(null,'',hash);else history.replaceState(null,'',hash);}
    if(state.ready)await loadSection();}
