  loadVideos=async function(){await refreshProjects();};
  async function syncLicenseScope() {
    const projectId=el('lic-course').value;
    if(projectId&&projectId!==activeId()){el('up-course').value=projectId;await selectCourse();el('lic-course').value=projectId;}
  }
  genLicenses=async function() {
    if(state.generatingLicense||el('lic-btn').disabled)return;
    state.generatingLicense=true;
    const courseDisabled=el('lic-course').disabled,scopeDisabled=el('up-course').disabled;
    try {
      await syncLicenseScope();
      state.licenseGenerationProject=el('lic-course').value;
      el('lic-course').disabled=true;el('up-course').disabled=true;
      el('license-search').value='';el('license-status-filter').value='';el('license-lot-filter').value='';state.licenseTab='available';
      await original.genLicenses();
    }catch(error){message('lic-msg',error.message,'err');}
    finally{state.generatingLicense=false;state.licenseGenerationProject='';el('lic-course').disabled=courseDisabled;el('up-course').disabled=scopeDisabled;}
  };
