  showApp=async function(){await original.showApp();if(!TOKEN||el('app').classList.contains('hidden'))return;state.ready=true;try{state.mailConfigured=!!(await req('GET','/account')).mail?.configured;}catch(_){}try{const saved=sessionStorage.getItem('edulock-active-project:'+(_me.id||''));if(saved&&state.projects.some(p=>p.id===saved)){el('up-course').value=saved;await original.selectCourse();}}catch(_){}await navigate(location.hash.slice(1));};
  logout= function(){state.ready=false;state.version++;state.projects=[];state.unassignedVideos=[];state.mailConfigured=false;state.licenses=[];state.lots=[];state.students=[];state.storage=[];state.licenseCounts=null;const dialog=el('workspace-dialog');if(dialog.open)dialog.close();const classDialog=el('class-dialog');if(classDialog?.open)classDialog.close();closeMenu();el('content-tree')?.replaceChildren();el('project-grid')?.replaceChildren();el('workspace-dialog-body').replaceChildren();el('workspace-form').onsubmit=null;el('integration-keys')?.replaceChildren();el('license-list')?.replaceChildren();el('workspace-students')?.replaceChildren();original.logout();};
